package watch

import (
	"context"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"
)

// The adapter tests drive the REAL fsnotify watcher through Run over
// t.TempDir trees. Real event delivery is asynchronous, so stimulus →
// observation is polled with deadlines; the TIMING DECISIONS themselves
// stay in the engine (D3 — synthetic times there, no sleeps in policy).
//
// Two configs: eventInterval turns the reconcile backstop OFF (an hour —
// no tick fires inside a test) so any observed scan must have come
// through the event path; tickInterval turns it ON for the backstop
// tests, where no filesystem event is produced at all.
const (
	eventInterval = time.Hour
	tickInterval  = 50 * time.Millisecond
	testDebounce  = 50 * time.Millisecond
	waitLimit     = 5 * time.Second
	settleDelay   = 250 * time.Millisecond
)

// libSet is the mutable library registry behind the Deps.Libraries
// closure — reconcile tests mutate it mid-run to drive the D6 diff.
type libSet struct {
	mu   sync.Mutex
	libs []Library
}

func (l *libSet) set(libs []Library) { l.mu.Lock(); l.libs = libs; l.mu.Unlock() }

func (l *libSet) list(context.Context) ([]Library, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return append([]Library(nil), l.libs...), nil
}

// scanLog records Deps.Scan calls; waiters poll the log per library id.
type scanLog struct {
	mu    sync.Mutex
	fired []int64
}

func newScanLog() *scanLog { return &scanLog{} }

func (s *scanLog) scan(_ context.Context, id int64) error {
	s.mu.Lock()
	s.fired = append(s.fired, id)
	s.mu.Unlock()
	return nil
}

func (s *scanLog) count() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.fired)
}

func (s *scanLog) ids() []int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]int64(nil), s.fired...)
}

func (s *scanLog) countOf(id int64) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, fired := range s.fired {
		if fired == id {
			n++
		}
	}
	return n
}

// waitScan blocks until library id has been scanned at least n times.
// Polling the log (not the channel) keeps per-library waits independent —
// a wait for one library never consumes another's observation.
func (s *scanLog) waitScan(t *testing.T, id int64, n int, limit time.Duration) {
	t.Helper()
	deadline := time.Now().Add(limit)
	for s.countOf(id) < n {
		if time.Now().After(deadline) {
			t.Fatalf("no %dth scan for library %d within %s; fired: %v", n, id, limit, s.ids())
		}
		time.Sleep(10 * time.Millisecond)
	}
}

func (s *scanLog) waitCount(t *testing.T, n int, limit time.Duration) {
	t.Helper()
	deadline := time.Now().Add(limit)
	for s.count() < n {
		if time.Now().After(deadline) {
			t.Fatalf("expected %d scans within %s, got %d: %v", n, limit, s.count(), s.ids())
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// start launches Run against the given closures and registers cleanup.
// It returns the cancel func and the channel carrying Run's return.
func start(t *testing.T, libs *libSet, log *scanLog, interval, debounce time.Duration) (context.CancelFunc, <-chan error) {
	t.Helper()
	svc := NewService(
		Deps{Libraries: libs.list, Scan: func(ctx context.Context, id int64) error { return log.scan(ctx, id) }},
		Config{ReconcileInterval: interval, Debounce: debounce},
	)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- svc.Run(ctx) }()
	t.Cleanup(cancel)
	return cancel, done
}

// settle gives Run's initial recursive install time to land before the
// first stimulus; installation is synchronous CPU-local work after Run
// starts, so the delay only needs to beat goroutine scheduling.
func settle() { time.Sleep(settleDelay) }

func write(t *testing.T, dir, name string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, name), []byte("fixture"), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestRunInstallsRecursiveWatches(t *testing.T) {
	root := t.TempDir()
	deep := filepath.Join(root, "a", "b", "c")
	if err := os.MkdirAll(deep, 0o755); err != nil {
		t.Fatal(err)
	}
	libs := &libSet{libs: []Library{{ID: 1, RootPath: root}}}
	log := newScanLog()
	cancel, _ := start(t, libs, log, eventInterval, testDebounce)
	defer cancel()

	settle()
	write(t, deep, "movie.mkv") // an event two levels below the root

	log.waitScan(t, 1, 1, waitLimit) // it reached the engine
}

func TestRunMapsEventsToOwningLibrary(t *testing.T) {
	rootA, rootB := t.TempDir(), t.TempDir()
	libs := &libSet{libs: []Library{{ID: 1, RootPath: rootA}, {ID: 2, RootPath: rootB}}}
	log := newScanLog()
	cancel, _ := start(t, libs, log, eventInterval, testDebounce)
	defer cancel()

	settle()
	write(t, rootA, "a.mkv")
	write(t, rootB, "b.mkv")

	log.waitScan(t, 1, 1, waitLimit)
	log.waitScan(t, 2, 1, waitLimit)
	// The backstop is off (eventInterval): every fired scan came from an
	// event, and only libraries 1 and 2 exist to own events.
	for _, id := range log.ids() {
		if id != 1 && id != 2 {
			t.Fatalf("scan fired for unknown library %d; fired: %v", id, log.ids())
		}
	}
}

func TestRunDirCreateExtendsWatchSet(t *testing.T) {
	root := t.TempDir()
	libs := &libSet{libs: []Library{{ID: 1, RootPath: root}}}
	log := newScanLog()
	cancel, _ := start(t, libs, log, eventInterval, testDebounce)
	defer cancel()

	settle()
	newDir := filepath.Join(root, "new")
	if err := os.Mkdir(newDir, 0o755); err != nil {
		t.Fatal(err)
	}
	log.waitScan(t, 1, 1, waitLimit)   // the mkdir itself takes the ordinary event path
	time.Sleep(200 * time.Millisecond) // let that scan complete and disarm

	// Without the extended watch set the file's event is invisible (the
	// reconcile backstop is off at eventInterval) — a SECOND scan can only
	// mean the new directory was being watched.
	write(t, newDir, "late.mkv")
	log.waitScan(t, 1, 2, waitLimit)
}

func TestRunReconcileRefreshesLibrarySet(t *testing.T) {
	root := t.TempDir()
	libs := &libSet{} // empty at boot — nothing watched initially
	log := newScanLog()
	cancel, _ := start(t, libs, log, tickInterval, testDebounce)
	defer cancel()

	settle()
	libs.set([]Library{{ID: 1, RootPath: root}})

	// No filesystem event anywhere: only a reconcile tick can have armed
	// library 1 — the D6 diff installed it and the backstop scanned it.
	log.waitScan(t, 1, 1, 2*time.Second)
}

func TestRunReconcileDropsDeletedLibrary(t *testing.T) {
	root := t.TempDir()
	libs := &libSet{libs: []Library{{ID: 1, RootPath: root}}}
	log := newScanLog()
	cancel, _ := start(t, libs, log, tickInterval, testDebounce)
	defer cancel()

	settle()
	log.waitScan(t, 1, 1, 2*time.Second)
	libs.set(nil)

	// Let several quiet ticks pass, snapshot, then confirm the count is
	// frozen over another run of ticks — library 1 no longer triggers.
	time.Sleep(10 * tickInterval)
	before := log.count()
	time.Sleep(10 * tickInterval)
	if after := log.count(); after != before {
		t.Fatalf("dropped library still scanned: %d → %d scans across quiet ticks", before, after)
	}
}

func TestRunReconcileTickTriggersScans(t *testing.T) {
	root := t.TempDir() // no filesystem events will be produced at all
	libs := &libSet{libs: []Library{{ID: 1, RootPath: root}}}
	log := newScanLog()
	cancel, _ := start(t, libs, log, tickInterval, testDebounce)
	defer cancel()

	// The quiet-period backstop: a watched library is scanned once per
	// tick even in total silence — prove recurrence, not a one-shot.
	log.waitCount(t, 3, 3*time.Second)
}

func TestRunStopsOnContextCancel(t *testing.T) {
	root := t.TempDir()
	libs := &libSet{libs: []Library{{ID: 1, RootPath: root}}}
	log := newScanLog()
	cancel, done := start(t, libs, log, tickInterval, testDebounce)

	settle()
	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("Run returned %v on context cancel, want nil", err)
		}
	case <-time.After(waitLimit):
		t.Fatal("Run did not return after context cancel")
	}
}
